ar": null, "death_year": null, "description": "据《资治通鉴》，907年在“李思安进攻幽州，被刘守光击退”中为卢龙节度使。", "biography": null, "status": "draft", "id": "b8f07571-c891-57ce-b69c-3e4a58148227"}, {"name": "刘守文", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“刘守文起兵攻打刘守光”中为进攻者。", "biography": null, "status": "draft", "id": "8d818778-5c92-5bc7-aa3e-0a5887582536"}, {"name": "王建", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“蜀王与晋王讨论讨梁及称帝”中为致书提议者。", "biography": null, "status": "draft", "id": "b02193d6-1c17-5154-bb7c-3295ed8dbbec"}, {"name": "李克用", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 908, "description": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "biography": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "status": "draft", "id": "04af206e-fa86-581c-86b9-87a78a8d59a5"}, {"name": "李存勖", "aliases": ["李存勗", "李亚子", "后唐庄宗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "908年继承晋王之位，923年在魏州称帝，国号唐；同年率军灭后梁。", "biography": "908年继承晋王之位，923年在魏州称帝，国号唐；同年率军灭后梁。", "status": "draft", "id": "4e068da9-c8dd-5a31-a747-87669e3bf993"}, {"name": "李溥", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷265天祐三年条所见人物：李溥。", "biography": null, "status": "draft", "id": "061f5da0-b3cc-599c-bf54-0ac227f0d4ab"}, {"name": "周德威", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“梁军围攻潞州，晋军出兵救援”中为救援将领。", "biography": null, "status": "draft", "id": "78a7d664-601e-54e7-852f-67032f549cde"}, {"name": "李嗣昭", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“梁军围攻潞州，晋军出兵救援”中为守城者。", "biography": null, "status": "draft", "id": "7ebbec0f-f2d1-52fd-a1c8-d4feeef63d83"}, {"name": "康怀英", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷263天复二年条所见人物：康怀英。", "biography": null, "status": "draft", "id": 